// 1. Airtable에서 검색된 모든 레코드를 가져옵니다.
const items = $input.all();

if (items.length === 0) {
  return [{ json: { text: "📍 현재 등록된 출발지가 없습니다." } }];
}

// 2. 각 레코드에서 이름과 장소를 안전하게 추출합니다.
const list = items.map((item, index) => {
  // fields가 없을 경우를 대비해 빈 객체({})를 기본값으로 설정
  const fields = item.json.fields || item.json || {}; 
  const name = fields.user_name || "이름없음";
  const location = fields.location_name || "장소미정";

  return `${index + 1}. ${name}: ${location}`;
}).join('\n');

// 3. 최종 메시지 형식
const finalMessage = `🔍 **현재 출발지 등록 현황**\n\n${list}\n\n💡 더 등록할 분이 없다면\n\n 📅 장소 추천 버튼을 눌러주세요!`;

return [{ json: { text: finalMessage } }];

