// 1. 노드 참조
const webhook = $('Webhook1').first().json.body;
const aggregate = $('Aggregate1').first().json;
const openWeather = $('OpenWeatherMap1').first().json; // 5일 예보 데이터

const targetDate = webhook.selected_date; // 사용자가 선택한 날짜 (예: 2026-01-10)

// 2. 날씨 데이터에서 해당 날짜만 필터링하여 최고/최저 계산
const forecastList = openWeather.list || [];
const dayData = forecastList.filter(item => item.dt_txt.includes(targetDate));

let weatherInfo = {
  min_temp: "0.0",
  max_temp: "0.0",
  avg_temp: "0.0",
  max_pop: 0,
  status: "정보 없음"
};

if (dayData.length > 0) {
  const temps = dayData.map(item => item.main.temp);
  const pops = dayData.map(item => item.pop);

  const min = Math.min(...temps);
  const max = Math.max(...temps);

  weatherInfo = {
    min_temp: min.toFixed(1),
    max_temp: max.toFixed(1),
    avg_temp: ((min + max) / 2).toFixed(1),
    max_pop: Math.max(...pops) * 100,
    status: dayData[Math.floor(dayData.length / 2)].weather[0].description // 낮 시간대 상태
  };
}

// 3. 참여자 정보 정리
const nameList = aggregate.user_name || [];
const locationList = aggregate.location_name || [];
const interests = aggregate.interest || [];

// 4. 최종 결과 반환
return [{
  json: {
    selected_date: targetDate || "날짜 미지정",
    participant_count: nameList.length,
    participants: nameList.join(', '),
    locations: locationList.join(' | '),
    interests: interests.length > 0 ? (Array.isArray(interests) ? interests.join(', ') : interests) : "맛집 및 핫플레이스",
    weather: weatherInfo // 계산된 날씨 정보
  }
}];

// 1. Search 노드에서 넘어온 전체 아이템 가져오기
const items = $input.all();
let message = "";

// 2. 검색 결과 유무 확인
if (items.length === 0 || !items[0].json || Object.keys(items[0].json).length === 0) {
    message = "⚠️ 아직 등록된 정보가 없습니다.\n\n먼저 정보를 등록해주세요!";
} 
else {
    // 3. 내 정보 추출 (image_776c41 구조 반영)
    const data = items[0].json;

    // Airtable 실제 컬럼명(image_777780)에 맞춰 매핑
    const name = data['user_name'] || "미등록";
    const addr = data['location_name'] || "미등록"; // 'address' 대신 'location_name' 사용
    const interest = data['interest'] || "미등록";

    message = "👤 [나의 등록 정보 확인]\n\n";
    message += `🏷️ 성함: ${name}\n`;
    message += `📍 출발지: ${addr}\n`;
    message += `🎯 관심사: ${interest}\n\n`;
    message += "위 정보를 수정하시려면 다시 등록 과정을 진행해주세요.";
}

// 4. n8n 표준 형식으로 반환
return [{ json: { message: message } }];

